                    fieldMasks[0] = ptNibbleMask;
                    fieldMasks[2] = ~(0xffffffffffffffL << ((carry + 4) & 0x3f)) & 0xffffffffffffffL;
                    carry = g_calc.getInt(0x28);
                    prevCarry = g_calc.getInt(0x2c);
